SELECT COUNT(*), ROUND(SUM(s.closing_balance),0), ROUND(100*SUM(s.closing_balance)/(SELECT SUM(closing_balance) FROM loan_monthly_snapshot WHERE snapshot_date = DATE '2025-12-31' AND loan_status <> 'Closed'),2), ROUND(SUM(s.closing_balance*s.interest_rate_pct)/SUM(s.closing_balance),3) FROM loan_monthly_snapshot s JOIN loan l USING (loan_id) JOIN property pr ON pr.property_id=l.property_id JOIN dim_postcode d ON d.postcode=pr.postcode WHERE s.snapshot_date = DATE '2025-12-31' AND s.loan_status <> 'Closed' AND d.state='NT'
